{
  "findings": [
    {
      "check_id": "CKV_GCP_117",
      "title": "Basic role used at project level",
      "resource": "google_project_iam_binding.trading_platform_admin",
      "severity": "MEDIUM",
      "explanation": "The 'roles/editor' role is a basic role that grants excessive permissions at the project level, potentially allowing unintended actions."
    }
  ],
  "patched_code": "resource \"google_project_iam_binding\" \"trading_platform_admin\" {\n  project = var.project_id\n  role    = \"roles/iam.serviceAccountUser\"\n  members = [\n    \"user:trader@${var.organization_domain}\",\n    \"user:admin@${var.organization_domain}\",\n  ]\n}",
  "fix_summary": "Replaced 'roles/editor' with a more restrictive role 'roles/iam.serviceAccountUser' to minimize permissions granted to users."
}
